    fr: "Une liste de garde que personne ne peut vérifier est une liste d’affirmations : la vérification est donc affichée au-dessus de la liste, pas en dessous.",
    de: "Eine Verwahrliste, die niemand prüfen kann, ist eine Liste von Behauptungen; deshalb steht die Verifikation über der Liste und nicht darunter.",
    pt: "Uma lista de custódia que ninguém pode verificar é uma lista de afirmações, por isso a verificação aparece acima da lista e não por baixo.",
    it: "Un elenco di custodia che nessuno può verificare è un elenco di affermazioni, perciò la verifica compare sopra l’elenco e non sotto.",
    ja: "誰にも確かめられない保管記録は主張の一覧にすぎません。だから検証結果は一覧の下ではなく上に表示します。",
    zh: "无人能核对的保管清单只是一串说法，因此验证结果显示在清单之上，而不是之下。",
    hi: "जिस अभिरक्षा सूची को कोई जाँच न सके वह दावों की सूची है, इसलिए सत्यापन सूची के नीचे नहीं, ऊपर दिखाया जाता है।",
    ar: "قائمة حيازة لا يستطيع أحد التحقق منها هي قائمة ادعاءات، لذا يُعرض التحقق فوق القائمة لا تحتها.",
