  "exc.once": {
    en: "The receive token comes back once, here, and is never served again. Use Copy the recipient’s link on the transfer below and send them that — it carries the token in the URL fragment, which browsers never transmit to a server, so the link can pass through mail without leaving the token in anybody’s logs. It is the thing that opens this transfer and nothing else opens it.",
    es: "El token de recepción se devuelve una sola vez, aquí, y no vuelve a servirse. Use Copiar el enlace del destinatario en la transferencia de abajo y envíeselo: lleva el token en el fragmento de la URL, que los navegadores nunca transmiten a un servidor, así que el enlace puede pasar por correo sin dejar el token en los registros de nadie. Es lo que abre esta transferencia y nada más la abre.",
    fr: "Le jeton de réception n’est renvoyé qu’une fois, ici, et n’est plus jamais servi. Utiliser Copier le lien du destinataire sur le transfert ci-dessous et le lui envoyer — il porte le jeton dans le fragment de l’URL, que les navigateurs ne transmettent jamais à un serveur : le lien peut donc passer par messagerie sans laisser le jeton dans les journaux de qui que ce soit. C’est ce qui ouvre ce transfert, et rien d’autre ne l’ouvre.",
    de: "Das Empfangs-Token kommt genau einmal zurück, hier, und wird nie wieder ausgeliefert. Über Empfängerlink kopieren beim Transfer unten weitergeben — es steht im URL-Fragment, das Browser nie an einen Server senden, sodass der Link per Mail laufen kann, ohne das Token in irgendwelchen Logs zu hinterlassen. Es ist das, was diesen Transfer öffnet, und nichts sonst öffnet ihn.",
    pt: "O token de receção volta uma única vez, aqui, e nunca mais é servido. Use Copiar a ligação do destinatário na transferência abaixo e envie-lha — leva o token no fragmento do URL, que os navegadores nunca transmitem a um servidor, pelo que a ligação pode seguir por correio sem deixar o token nos registos de ninguém. É o que abre esta transferência e nada mais a abre.",
    it: "Il token di ricezione torna una sola volta, qui, e non viene più servito. Usare Copiare il link del destinatario sul trasferimento qui sotto e inviarglielo — porta il token nel frammento dell’URL, che i browser non trasmettono mai a un server, così il link può passare per posta senza lasciare il token nei log di nessuno. È ciò che apre questo trasferimento e nient’altro lo apre.",
    ja: "受取トークンが返るのはここで一度きりで、二度と提供されません。下の転送で「受取人のリンクをコピー」を使い、それを相手に送ってください。トークンは URL フラグメントに入っており、ブラウザーはこれをサーバーへ送信しないため、リンクはメールを通っても誰のログにもトークンを残しません。この転送を開けるのはそれだけで、ほかには何もありません。",
    zh: "接收令牌只在此处返回一次，之后不再提供。请在下方的传输上使用“复制接收方链接”并发送给对方 — 令牌位于 URL 片段中，浏览器从不将其发送给服务器，因此链接可以通过邮件传递而不会把令牌留在任何人的日志里。能打开这次传输的只有它，别无其他。",
    hi: "प्राप्ति टोकन यहाँ केवल एक बार लौटता है और फिर कभी नहीं दिया जाता। नीचे के स्थानांतरण पर “प्राप्तकर्ता का लिंक कॉपी करें” का उपयोग करें और वही उन्हें भेजें — यह टोकन को URL फ़्रैगमेंट में रखता है, जिसे ब्राउज़र कभी सर्वर तक नहीं भेजते, इसलिए लिंक डाक से गुज़र सकता है बिना किसी के लॉग में टोकन छोड़े। यही इस स्थानांतरण को खोलता है और कुछ और नहीं खोलता।",
    ar: "يعود رمز الاستلام مرة واحدة فقط، هنا، ولا يُقدَّم مرة أخرى أبدًا. استخدم «انسخ رابط المستلم» على التحويل أدناه وأرسله إليه — فهو يحمل الرمز في جزء العنوان الذي لا ترسله المتصفحات إلى أي خادم، فيمكن للرابط أن يمرّ عبر البريد دون أن يترك الرمز في سجلات أحد. هو ما يفتح هذا التحويل، ولا شيء غيره يفتحه.",
  },
