  "exc.onewaydoor": {
    en: "An intake is a one-way door somebody else walks through. The submit token is theirs, not yours — the same shape as a receive token and for the same reason.",
    es: "Una recepción es una puerta de un solo sentido por la que pasa otra persona. El token de envío es suyo, no tuyo: la misma forma que un token de recepción y por la misma razón.",
    fr: "Une réception est une porte à sens unique que quelqu’un d’autre franchit. Le jeton de dépôt est le sien, pas le vôtre — même forme qu’un jeton de réception, et pour la même raison.",
    de: "Eine Annahme ist eine Einbahntür, durch die jemand anderes geht. Das Einreich-Token gehört ihr, nicht dir — dieselbe Form wie ein Empfangs-Token und aus demselben Grund.",
    pt: "Uma receção é uma porta de sentido único por onde outra pessoa passa. O token de envio é dela, não seu — a mesma forma de um token de receção e pela mesma razão.",
    it: "Un’accettazione è una porta a senso unico che attraversa qualcun altro. Il token di invio è suo, non vostro — la stessa forma di un token di ricezione e per la stessa ragione.",
    ja: "受け入れ口は、他の誰かが通る一方通行の扉です。提出トークンはその人のものであって、あなたのものではありません。受取トークンと同じ形で、同じ理由によります。",
    zh: "接收口是一扇由别人穿过的单向门。提交令牌属于对方，不属于你 — 与接收令牌形状相同，理由也相同。",
    hi: "इनटेक एक एकतरफ़ा दरवाज़ा है जिससे कोई और गुज़रता है। सबमिट टोकन उनका है, आपका नहीं — प्राप्ति टोकन जैसा ही आकार, उसी कारण से।",
    ar: "المدخل باب باتجاه واحد يعبره شخص آخر. رمز الإرسال له لا لك — بالشكل نفسه الذي لرمز الاستلام وللسبب نفسه.",
  },
