    fr: "Notre responsabilité :", de: "Unsere Verantwortung:",
    pt: "A nossa responsabilidade:", it: "La nostra responsabilità:",
    ja: "当方の責任範囲:", zh: "我方负责：", hi: "हमारी ज़िम्मेदारी:",
    ar: "مسؤوليتنا:",
