  // -- bridges: what reaches into this vault ------------------------------
  //
  // Wired at 0.60.6. Seventeen routes' worth of ways for something outside
  // PDI to put material inside it — a connected account, a robot in a
  // building, another product handing over what it learned.
  //
  // The two paragraphs that matter are the ones that say what the vault
  // will *not* do: a contribution listing is a count and a set of keys and
  // never contents, and a bound robot's readings are sealed like anything
  // else. A promise about custody only counts if the person reading it can
  // read it, which is the whole argument for this file.
