  "bri.robots.note": {
    en: "The model has to be one the catalogue knows — an unknown one is a 404 rather than a row nobody can act on. Everything a bound robot sends in is sealed under this tenant's key like anything else.",
    es: "El modelo tiene que ser uno que el catálogo conozca: uno desconocido devuelve un 404 en lugar de una fila sobre la que nadie puede actuar. Todo lo que envía un robot vinculado se sella con la clave de este inquilino, como cualquier otra cosa.",
    fr: "Le modèle doit être connu du catalogue — un modèle inconnu donne un 404 plutôt qu’une ligne sur laquelle personne ne peut agir. Tout ce qu’un robot lié envoie est scellé sous la clé de ce locataire, comme le reste.",
    de: "Das Modell muss dem Katalog bekannt sein — ein unbekanntes ergibt einen 404 statt einer Zeile, mit der niemand etwas anfangen kann. Alles, was ein gebundener Roboter hereinschickt, wird wie alles andere unter dem Schlüssel dieses Mandanten versiegelt.",
    pt: "O modelo tem de ser um que o catálogo conheça — um desconhecido devolve um 404 em vez de uma linha sobre a qual ninguém pode agir. Tudo o que um robô vinculado envia é selado com a chave deste inquilino, como tudo o resto.",
    it: "Il modello deve essere uno che il catalogo conosce: uno sconosciuto produce un 404 anziché una riga su cui nessuno può agire. Tutto ciò che un robot collegato invia viene sigillato con la chiave di questo tenant, come qualsiasi altra cosa.",
    ja: "機種はカタログが知っているものでなければなりません。未知の機種は、誰も扱えない行ではなく 404 を返します。登録済みのロボットが送ってくるものはすべて、他のものと同じくこのテナントの鍵で封印されます。",
    zh: "型号必须是目录已知的 — 未知型号会返回 404，而不是留下一行谁也无法处理的记录。已绑定机器人送进来的一切，都和其他数据一样，用该租户的密钥封存。",
    hi: "मॉडल वही हो सकता है जिसे सूची जानती हो — अज्ञात मॉडल पर 404 मिलता है, न कि ऐसी पंक्ति जिस पर कोई कार्रवाई न कर सके। बँधा हुआ रोबोट जो कुछ भी भेजता है, वह बाकी सब की तरह इस टेनेंट की कुंजी से सील होता है।",
    ar: "يجب أن يكون الطراز معروفًا في الفهرس — الطراز المجهول يعطي 404 بدلًا من صف لا يستطيع أحد التصرف بشأنه. وكل ما يرسله روبوت مربوط يُختم بمفتاح هذا المستأجر كأي شيء آخر.",
  },
