  // -- the last six screens ------------------------------------------------
  //
  // Keys, Overview, Audit, Operations, VaultLight and App. This is the round
  // that takes `console_untranslated.txt` to zero, so the record stops being a
  // backlog and becomes a floor.
  //
  // `ov.title` and `au.title` copy `tab.overview` and `tab.audit` from the
  // shells rather than wording them again — the same rule that governed
  // Records. `app.sub` is decided rather than assumed: *Private Data
  // Infrastructure* is what `PDI` stands for, and it is a description a reader
  // can only follow in a language they read, so it moves. The acronym does
  // not.
