  "prob.server": {
    en: "What has reached the server", es: "Lo que ha llegado al servidor",
    fr: "Ce qui a atteint le serveur", de: "Was den Server erreicht hat",
    pt: "O que chegou ao servidor", it: "Cosa è arrivato al server",
    ja: "サーバーに届いたもの", zh: "已到达服务器的内容",
    hi: "सर्वर तक क्या पहुँचा", ar: "ما وصل إلى الخادم",
  },
  "prob.server.pitch": {
    en: "Every client of this deployment reports its failures here, folded into counters — an operation, a status, a count, never anyone's content. Reading them is the operator's: use the PDI_PROBLEMS_KEY, or ask from the machine the backend runs on.",
    es: "Cada cliente de esta instalación informa aquí sus fallos, plegados en contadores: una operación, un estado, un recuento, nunca el contenido de nadie. Leerlos es del operador: usa la PDI_PROBLEMS_KEY o consulta desde la máquina donde corre el backend.",
    fr: "Chaque client de ce déploiement rapporte ici ses échecs, repliés en compteurs — une opération, un statut, un total, jamais le contenu de quiconque. Leur lecture revient à l'opérateur : utilisez la PDI_PROBLEMS_KEY, ou interrogez depuis la machine du backend.",
    de: "Jeder Client dieser Installation meldet seine Fehler hierher, zu Zählern gefaltet — eine Operation, ein Status, eine Anzahl, nie jemandes Inhalte. Lesen ist Sache des Betreibers: mit dem PDI_PROBLEMS_KEY, oder von der Maschine aus, auf der das Backend läuft.",
    pt: "Cada cliente desta instalação comunica aqui as suas falhas, dobradas em contadores — uma operação, um estado, uma contagem, nunca o conteúdo de ninguém. Lê-las é do operador: use a PDI_PROBLEMS_KEY ou pergunte a partir da máquina onde corre o backend.",
    it: "Ogni client di questa installazione riporta qui i suoi errori, ripiegati in contatori — un'operazione, uno stato, un conteggio, mai il contenuto di qualcuno. Leggerli spetta all'operatore: usa la PDI_PROBLEMS_KEY, oppure chiedi dalla macchina su cui gira il backend.",
    ja: "この配備のすべてのクライアントが障害をここに報告し、カウンターに畳み込まれます — 操作、ステータス、件数だけで、誰かの内容は決して含まれません。読むのは運用者の役目です。PDI_PROBLEMS_KEY を使うか、バックエンドが動く機械から尋ねてください。",
    zh: "此部署的每个客户端都把故障报告到这里，折叠成计数——操作、状态码、次数，绝不含任何人的内容。读取属于运维者：使用 PDI_PROBLEMS_KEY，或从后端所在的机器上查询。",
    hi: "इस परिनियोजन का हर क्लाइंट अपनी विफलताएँ यहाँ भेजता है, गिनतियों में समेटी हुई — एक ऑपरेशन, एक स्थिति, एक संख्या, कभी किसी की सामग्री नहीं। इन्हें पढ़ना संचालक का काम है: PDI_PROBLEMS_KEY इस्तेमाल करें, या उसी मशीन से पूछें जिस पर बैकएंड चलता है।",
    ar: "كل عميل في هذا النشر يبلّغ أعطاله هنا، مطويةً في عدّادات — عملية وحالة وعدد، ولا محتوى لأحد أبدًا. قراءتها للمشغّل: استخدم PDI_PROBLEMS_KEY، أو اسأل من الجهاز الذي يعمل عليه الخادم.",
  },
