  "res.signin": {
    en: "Enter a tenant token on the Tenants screen first — the resident works for a tenant.",
    es: "Introduce primero un token de inquilino en la pantalla Inquilinos: el residente trabaja para un inquilino.",
    fr: "Saisissez d'abord un jeton de locataire sur l'écran Locataires — le résident travaille pour un locataire.",
    de: "Gib zuerst auf dem Mandanten-Bildschirm ein Mandanten-Token ein — der Resident arbeitet für einen Mandanten.",
    pt: "Introduza primeiro um token de inquilino no ecrã Inquilinos — o residente trabalha para um inquilino.",
    it: "Inserisci prima un token del tenant nella schermata Tenant: il residente lavora per un tenant.",
    ja: "先にテナント画面でテナントトークンを入力してください — レジデントはテナントのために働きます。",
    zh: "请先在租户页面输入租户令牌 — 驻留智能为租户工作。",
    hi: "पहले टेनेंट स्क्रीन पर टेनेंट टोकन दर्ज करें — रेज़िडेंट किसी टेनेंट के लिए काम करता है।",
    ar: "أدخل رمز المستأجر في شاشة المستأجرين أولًا — يعمل المقيم لصالح مستأجر.",
  },
  "res.pitch": {
    en: "The agent living in the vault process: it plans multi-step tasks, calls tools from a closed registry, writes rows into tables you can query, embeds for vector search, and infers locally — no separate orchestration service, wherever the vault is hosted.",
    es: "El agente que vive en el proceso del vault: planifica tareas de varios pasos, llama a herramientas de un registro cerrado, escribe filas en tablas que puedes consultar, genera embeddings para búsqueda vectorial e infiere localmente — sin servicio de orquestación aparte, dondequiera que esté alojado el vault.",
    fr: "L'agent qui vit dans le processus du coffre : il planifie des tâches en plusieurs étapes, appelle des outils d'un registre fermé, écrit des lignes dans des tables interrogeables, génère des embeddings pour la recherche vectorielle et infère localement — sans service d'orchestration séparé, où que le coffre soit hébergé.",
    de: "Der Agent, der im Tresorprozess lebt: Er plant mehrstufige Aufgaben, ruft Werkzeuge aus einem geschlossenen Register auf, schreibt Zeilen in abfragbare Tabellen, erzeugt Embeddings für die Vektorsuche und inferiert lokal — ohne separaten Orchestrierungsdienst, wo auch immer der Tresor gehostet ist.",
    pt: "O agente que vive no processo do cofre: planeia tarefas de vários passos, chama ferramentas de um registo fechado, escreve linhas em tabelas consultáveis, gera embeddings para pesquisa vetorial e infere localmente — sem serviço de orquestração separado, onde quer que o cofre esteja alojado.",
    it: "L'agente che vive nel processo del vault: pianifica compiti in più passi, chiama strumenti da un registro chiuso, scrive righe in tabelle interrogabili, genera embedding per la ricerca vettoriale e inferisce in locale — senza servizio di orchestrazione separato, ovunque sia ospitato il vault.",
    ja: "ボールトのプロセス内に住むエージェントです。多段階のタスクを計画し、閉じたレジストリのツールを呼び出し、照会できるテーブルに行を書き込み、ベクトル検索用の埋め込みを作り、ローカルで推論します — 別のオーケストレーションサービスは不要で、ボールトがどこにホストされていても働きます。",
    zh: "住在保险库进程里的智能体：规划多步任务、调用封闭注册表中的工具、把行写进可查询的表、为向量搜索生成嵌入、在本地推理 — 无需单独的编排服务，无论保险库托管在哪里。",
    hi: "वॉल्ट प्रक्रिया के भीतर रहने वाला एजेंट: यह बहु-चरण कार्यों की योजना बनाता है, बंद रजिस्ट्री से उपकरण बुलाता है, ऐसी तालिकाओं में पंक्तियाँ लिखता है जिन्हें आप क्वेरी कर सकते हैं, वेक्टर खोज के लिए एम्बेडिंग बनाता है, और स्थानीय रूप से अनुमान लगाता है — कोई अलग ऑर्केस्ट्रेशन सेवा नहीं, वॉल्ट कहीं भी होस्ट हो।",
    ar: "الوكيل الذي يسكن داخل عملية الخزنة: يخطط مهامًا متعددة الخطوات، ويستدعي أدوات من سجل مغلق، ويكتب صفوفًا في جداول يمكنك الاستعلام عنها، وينشئ التضمينات للبحث المتجهي، ويستدل محليًا — من دون خدمة تنسيق منفصلة، أينما استُضيفت الخزنة.",
  },
